import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, CORE_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    assert.strictEqual(load('!!int +0b11', { schema: CORE_SCHEMA }), 3);
    assert.strictEqual(load('!!int -0b11', { schema: CORE_SCHEMA }), -3);
  });
});

